export const V1_NUMERIC_CHECKPOINT_169333_BASE64 = '';

export function exactV1NumericCheckpoint169333() {
  const fixture = JSON.parse(Buffer.from(V1_NUMERIC_CHECKPOINT_169333_BASE64, 'base64').toString('utf8'));
  return {
    ...fixture,
    events: fixture.entries.map((entry) => JSON.parse(entry.raw)),
    eventBlobs: Object.fromEntries(fixture.entries.map((entry) => [entry.path, entry.oid]))
  };
}

